import {esc,cash,icon,pageHead,row,field,dateLabel} from './ui.js';
import { reviewOutflowImpact } from './outflow-impact.js';
import { evaluatePayment } from './model.js';
import {ensurePaymentParityState} from './payments-parity-model.js';
const button=(title,action,secondary=true)=>`<button class="button${secondary?' secondary':''}" type="button" data-extra-action="${action}">${title}</button>`;
const money=(ctx,n)=>ctx.state.settings.hideBalance?'••••.••':cash(n);
const nonce=()=>globalThis.crypto?.randomUUID?.()||`card-${Date.now()}-${Math.random()}`;
export function selectedCard(ctx){ensurePaymentParityState(ctx.state);return ctx.state.virtualCards.find(c=>c.id===ctx.draft.selectedCardId)||ctx.state.virtualCard;}
export function renderCardsParity(ctx){ensurePaymentParityState(ctx.state);const c=selectedCard(ctx),cards=ctx.state.virtualCards,open=cards.filter(c=>c.status!=='closed');return `<section class="page payment-extras-page payment-cards-page">${pageHead('Virtual cards')}<div class="payment-extra-intro"><span class="eyebrow">PROTOTYPE ONLY</span><h1>Online spending,<br>kept separate.</h1><p>Keep online spending separate from Everyday.</p></div>${cards.length?`<div class="chips" aria-label="Choose a demo card">${cards.map(card=>`<button class="chip ${card.id===c?.id?'selected':''}" data-card-select="${esc(card.id)}">${esc(card.name)}${card.status==='closed'?' · Closed':''}</button>`).join('')}</div>`:''}<div class="payment-demo-card${c?.status==='frozen'?' is-frozen':''}"><div><span class="wordmark">lumo</span>${icon(c?.status==='frozen'?'lock':'card',22)}</div><strong>DEMO •••• ${c?esc(c.last4):'••••'}</strong><div><span>${esc(c?.name||'Virtual card')}</span><span>${c?esc(c.status):'Not created'}</span></div></div><p class="payment-card-demo-note">No live card is issued. No real card number or security code exists.</p>${c?`<div class="payment-card-balance"><span>Card balance</span><strong>${money(ctx,c.balance)}</strong></div><p class="muted small">${money(ctx,ctx.state.wallet)} in Everyday · Card money is separate.</p>${c.status!=='closed'?`<div class="payment-card-tools">${button('Add to card','card-fund',false)}${button('Return to Everyday','card-return')}${button(c.status==='frozen'?'Unfreeze demo card':'Freeze demo card','toggle-card')}${button('Card details','card-details')}</div><details class="payment-card-management"><summary>Manage card</summary><div class="panel">${row({title:'Rename card',sub:esc(c.name),action:'card-rename'})}${row({title:'Purchase limit',sub:money(ctx,c.limit)+' per purchase',action:'card-limit'})}${row({title:'Replace card',sub:'Keep unspent money; retire this card',action:'card-replace'})}${row({title:'Close card',sub:'Return its balance first',action:'card-close'})}</div></details><details class="parity-demo"><summary>Try an online purchase · simulation</summary><p class="muted small">Choose a sample merchant and outcome. No real purchase takes place.</p>${button('Make a demo purchase','card-purchase')}</details>`:'<p class="muted">This card is closed. Its payments and history are retained below.</p>'}<div class="section-label"><span>CARD ACTIVITY</span></div><div class="panel">${ctx.state.transactions.filter(t=>t.cardId===c.id).map(t=>`<div class="row"><span class="row-copy"><span class="row-title">${esc(t.merchant||'Card move')}</span><span class="row-sub">${esc(t.type.replaceAll('-',' '))} · ${esc(t.status)}${t.refunded?` · ${money(ctx,t.refunded)} refunded`:''}</span></span><strong>${money(ctx,t.amount)}</strong>${t.type==='card-purchase'&&t.status==='pending'?`<button class="text-button" data-card-purchase-id="${esc(t.id)}">Outcome</button>`:t.type==='card-purchase'&&t.status==='success'&&(t.refunded||0)<t.amount?`<button class="text-button" data-card-refund-id="${esc(t.id)}">Refund</button>`:''}</div>`).join('')||'<p class="muted">Your card moves will appear here.</p>'}</div>${c.history?.length?`<details><summary>Card history</summary>${c.history.map(e=>`<p class="muted small">${esc(e.type.replaceAll('-',' '))} · ${dateLabel(e.at)}</p>`).join('')}</details>`:''}`:''}${open.length<2?`<div class="payment-extra-bottom">${button(open.length?'Create another demo card':'Create demo virtual card','create-card',open.length>0)}</div>`:''}</section>`;}
function apply(ctx,type,payload={}){const result=ctx.act(type,{...payload,idempotencyKey:payload.idempotencyKey||nonce()});if(!result.ok){ctx.toast(result.message);return false;}if(type==='cardReplace'&&result.id)ctx.draft.selectedCardId=result.id;ctx.closeSheet();ctx.refresh();ctx.toast(result.message);return true;}
function authorize(ctx,title,type,payload){const intent={...payload,idempotencyKey:payload.idempotencyKey||nonce()};let settled=false;ctx.auth({title,onCancel:()=>{settled=true;},onSuccess:()=>{if(settled||ctx.route?.page&&ctx.route.page!=='cards')return;settled=true;apply(ctx,type,intent);}});}
export function handleCardParityClick(ctx,b){const c=selectedCard(ctx);if(b.dataset.cardSelect){ctx.draft.selectedCardId=b.dataset.cardSelect;ctx.refresh();return true;}
const a=b.dataset.extraAction||b.dataset.action;
if(b.dataset.cardPurchaseId&&c){const id=b.dataset.cardPurchaseId;ctx.sheet(`<h2>What did the merchant confirm?</h2><p>Participant simulation. A status check alone would keep this pending.</p>${button('Confirm purchase','purchase-confirm',false)}${button('Decline purchase','purchase-decline')}`,el=>{el.querySelector('[data-extra-action="purchase-confirm"]').onclick=()=>apply(ctx,'cardResolvePurchase',{cardId:c.id,transactionId:id,status:'success'});el.querySelector('[data-extra-action="purchase-decline"]').onclick=()=>apply(ctx,'cardResolvePurchase',{cardId:c.id,transactionId:id,status:'failed'});});return true;}
if(b.dataset.cardRefundId&&c){const t=ctx.state.transactions.find(t=>t.id===b.dataset.cardRefundId);if(!t)return true;moneySheet(ctx,{title:'A little money back.',label:'Refund to this card (GH₵)',value:(t.amount-(t.refunded||0))/100,onSubmit:amount=>authorize(ctx,'Confirm demo card refund?','cardRefund',{cardId:c.id,transactionId:t.id,amount})});return true;}
if(!['card-fund','card-return','card-purchase','card-rename','card-limit','card-close','card-replace'].includes(a))return false;if(!c||c.status==='closed'){ctx.toast('Choose an open card.');return true;}
if(a==='card-fund'||a==='card-return'){moneySheet(ctx,{title:a==='card-fund'?'Give your card a little fuel.':'Back to Everyday.',label:a==='card-fund'?'Move to this card (GH₵)':'Return to Everyday (GH₵)',value:a==='card-return'?c.balance/100:'',onSubmit:amount=>{ const proceed=()=>authorize(ctx,a==='card-fund'?'Move money to your card?':'Return card money to Everyday?',a==='card-fund'?'cardFund':'cardReturn',{cardId:c.id,amount}); if(a==='card-fund')reviewOutflowImpact(ctx,{amount,category:'Card transfer',merchant:c.name,title:'A little fuel. Room for your plans?',actionLabel:'Continue to PIN',onContinue:proceed,onEdit:()=>handleCardParityClick(ctx,{dataset:{extraAction:'card-fund'}})});else proceed();}});return true;}
if(a==='card-rename'){ctx.sheet(`<h2>Make it yours.</h2><form class="form-stack">${field({label:'Card name',name:'cardName',value:c.name})}<button class="button" type="submit">Save name</button></form>`,el=>{el.querySelector('form').onsubmit=e=>{e.preventDefault();apply(ctx,'cardRename',{cardId:c.id,name:el.querySelector('[name="cardName"]').value});};});return true;}
if(a==='card-limit'){moneySheet(ctx,{title:'A little limit for online life.',label:'Maximum per purchase (GH₵)',value:c.limit/100,onSubmit:limit=>authorize(ctx,'Update demo card limit?','cardLimit',{cardId:c.id,limit})});return true;}
if(a==='card-close'||a==='card-replace'){ctx.sheet(`<h2>${a==='card-close'?'Close this card?':'A fresh card. Same plans.'}</h2><p>${a==='card-close'?'Its balance must be zero and purchases settled. Your history stays available.':'Your old card will close. Unspent money moves to its replacement. Pending purchases must finish first.'}</p>${button(a==='card-close'?'Review closure':'Review replacement','card-confirm',false)}`,el=>{el.querySelector('[data-extra-action="card-confirm"]').onclick=()=>authorize(ctx,a==='card-close'?'Close demo card?':'Replace demo card?',a==='card-close'?'cardClose':'cardReplace',{cardId:c.id});});return true;}
if(a==='card-purchase'){ctx.sheet(`<h2>What’s the online plan?</h2><p class="muted small">Demo purchase only. No merchant is connected.</p><form class="form-stack">${field({label:'Sample merchant',name:'merchant',placeholder:'e.g. Study supplies'})}${field({label:'Amount (GH₵)',name:'amount',type:'number',min:'0.01'})}<details class="parity-demo"><summary>Plan details · optional</summary><label class="field"><span>Category</span><select class="input" name="category">${['Personal','Food','Transport','Data','Essentials','Other'].map(category=>`<option>${category}</option>`).join('')}</select></label></details><label class="field"><span>Simulated outcome</span><select class="input" name="outcome"><option value="success">Confirmed purchase</option><option value="pending">Awaiting merchant</option><option value="failed">Declined purchase</option></select></label><button class="button" type="submit">Review purchase</button></form>`,el=>{const form=el.querySelector('form'),actionKey=nonce();form.onsubmit=e=>{e.preventDefault();const payload={cardId:c.id,merchant:form.elements.merchant.value,amount:/^\d+(?:\.\d{1,2})?$/.test(form.elements.amount.value)?Math.round(Number(form.elements.amount.value)*100):NaN,category:form.elements.category.value,status:form.elements.outcome.value,idempotencyKey:actionKey};reviewCardPurchase(ctx,c,payload);};});return true;}return true;}
function moneySheet(ctx,{title,label,value,onSubmit}){ctx.sheet(`<h2>${title}</h2><form class="form-stack">${field({label,name:'amount',type:'number',min:'0.01',value})}<p class="error" role="alert"></p><button class="button" type="submit">Review</button></form>`,el=>{const form=el.querySelector('form');form.onsubmit=e=>{e.preventDefault();const raw=form.elements.amount.value,amount=Math.round(Number(raw)*100);if(!/^\d+(?:\.\d{1,2})?$/.test(raw)||amount<=0){form.querySelector('.error').textContent='Use an amount above zero, with up to two decimal places.';return;}onSubmit(amount);};});}

function reviewCardPurchase(ctx, c, payload) {
  if (!Number.isSafeInteger(payload.amount) || payload.amount <= 0 || payload.amount > c.balance) return ctx.toast('Use an amount within your card balance.');
  if (payload.amount > c.limit) return ctx.toast('That is above this card’s purchase limit.');
  if (!payload.merchant.trim()) return ctx.toast('Name the demo merchant.');
  const impact = evaluatePayment({ ...ctx.state, wallet: ctx.state.wallet + c.balance }, { ...payload, rail: 'card', fee: 0 });
  const category = ctx.state.budget.items.find(item => item.id === impact.budgetItemId);
  let continued = false;
  ctx.sheet(`<section class="outflow-impact"><p class="eyebrow">Demo card purchase</p><h2>${esc(cash(payload.amount))} at ${esc(payload.merchant)}</h2><dl><div><dt>Card after purchase</dt><dd>${esc(cash(c.balance - payload.amount))}</dd></div><div><dt>Everyday</dt><dd>Unchanged</dd></div><div><dt>Category</dt><dd>${esc(category?.name || payload.category)}</dd></div></dl><p class="muted">${category ? `This counts towards your ${esc(category.name)} plan once the money is taken. A declined payment releases it.` : 'This is recorded as card spending. Moving money onto your card is not counted again.'}</p><p class="muted small">This is a participant simulation. No real merchant is connected.</p><button class="button" type="button" data-card-purchase-continue>Continue to PIN</button></section>`, root => { root.querySelector('[data-card-purchase-continue]').onclick = () => { if (continued) return; continued = true; ctx.closeSheet(); authorize(ctx,'Confirm demo card purchase?','cardPurchase',payload); }; });
}
